\set ON_ERROR_STOP on
set timezone='UTC';
create schema profile_avatar_test;
create function profile_avatar_test.id(n integer) returns uuid language sql immutable as $$select ('99890000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create table profile_avatar_test.ids(key text primary key,id uuid not null);
create table profile_avatar_test.cases(name text primary key,identity jsonb not null,request jsonb not null,receipt jsonb not null);
create table profile_avatar_test.states(name text primary key,identity jsonb not null,state jsonb not null);
create table profile_avatar_test.pending(key text primary key,request jsonb not null);
grant usage on schema profile_avatar_test to authenticated;
grant select,insert on all tables in schema profile_avatar_test to authenticated;
insert into auth.users(id,email) select profile_avatar_test.id(n),'avatar-'||n||'@example.test' from generate_series(1,4) n;
select set_config('request.jwt.claim.sub',profile_avatar_test.id(1)::text,false);
insert into profile_avatar_test.ids select 'team',team_id from public.create_team_workspace('Avatar fixture','AVA-91023');
create function profile_avatar_test.team() returns uuid language sql stable as $$select id from profile_avatar_test.ids where key='team'$$;
insert into public.team_members(id,team_id,profile_id,role,status,created_at) values(profile_avatar_test.id(10),profile_avatar_test.team(),profile_avatar_test.id(3),'member','active','2026-10-23T03:04:05.123456Z');
update public.profiles set avatar_url='https://legacy.example.test/retained',full_name='Preserved name' where id=profile_avatar_test.id(3);
create function profile_avatar_test.identity() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('userId',auth.uid(),'teamId',m.team_id,'memberId',m.id,'role',m.role,'teamName',t.name,'permissions','[]'::jsonb) from public.team_members m join public.teams t on t.id=m.team_id where m.team_id=profile_avatar_test.team() and m.profile_id=auth.uid()$$;
create function profile_avatar_test.request(n integer) returns jsonb language sql stable security definer set search_path='' set timezone='UTC' as $$
 select jsonb_build_object('version',2,'userId',auth.uid(),'teamId',m.team_id,'memberId',m.id,'requestNonce',profile_avatar_test.id(n),
 'base',jsonb_build_object('avatarUrl',p.avatar_url,'memberCreatedAt',m.created_at),'value',jsonb_build_object('objectPath',auth.uid()::text||'/'||profile_avatar_test.id(n)::text||'.png','sha256','4c4b6a3be1314ab86138bef4314dde022e600960d8689a2c8f8631802d20dab6','mimeType','image/png','sizeBytes',8))
 from public.team_members m join public.profiles p on p.id=m.profile_id where m.team_id=profile_avatar_test.team() and m.profile_id=auth.uid();
$$;
create function profile_avatar_test.object(request jsonb) returns void language sql security definer set search_path='' as $$insert into storage.objects(bucket_id,name,owner,owner_id,metadata) values('profile-avatars',request#>>'{value,objectPath}',auth.uid(),auth.uid()::text,jsonb_build_object('mimetype','image/png','size',8))$$;
create function profile_avatar_test.rpc(request jsonb) returns jsonb language sql as $$select public.mobile_apply_profile_avatar((request->>'teamId')::uuid,(request->>'memberId')::uuid,request,'https://avatar-project.supabase.co/storage/v1/object/public/profile-avatars/'||(request#>>'{value,objectPath}'))$$;
create function profile_avatar_test.capture(label text,request jsonb) returns jsonb language plpgsql as $$declare result jsonb;begin result:=profile_avatar_test.rpc(request);insert into profile_avatar_test.cases values(label,profile_avatar_test.identity(),request,result);return result;end$$;
create function profile_avatar_test.state(label text) returns jsonb language plpgsql as $$declare identity jsonb:=profile_avatar_test.identity();result jsonb;begin result:=public.mobile_read_profile_avatar_state(profile_avatar_test.team(),(identity->>'memberId')::uuid);insert into profile_avatar_test.states values(label,identity,result);return result;end$$;
create function profile_avatar_test.denied(request jsonb,expected text) returns void language plpgsql as $$declare denied boolean:=false;begin begin perform profile_avatar_test.rpc(request);exception when others then if sqlstate=expected then denied:=true;else raise;end if;end;assert denied,'Expected avatar denial '||expected;end$$;
select set_config('request.jwt.claim.sub',profile_avatar_test.id(3)::text,false);
set role authenticated;
select profile_avatar_test.state('precise-member');
insert into profile_avatar_test.pending values('applied',profile_avatar_test.request(200));
select profile_avatar_test.denied(profile_avatar_test.request(200)||'{"extra":true}','22023');
select profile_avatar_test.denied(jsonb_set(profile_avatar_test.request(200),'{value,objectPath}','"other/photo.png"'),'22023');
select profile_avatar_test.denied(jsonb_set(profile_avatar_test.request(200),'{base,memberCreatedAt}','"2026-10-23T03:04:05.123457Z"'),'42501');
select profile_avatar_test.denied(profile_avatar_test.request(200),'22023');
select profile_avatar_test.object(profile_avatar_test.request(200));
select profile_avatar_test.capture('member-applied',profile_avatar_test.request(200));
insert into profile_avatar_test.pending values('cas',profile_avatar_test.request(201)),('late',profile_avatar_test.request(202)),('race',profile_avatar_test.request(203));
select profile_avatar_test.object(profile_avatar_test.request(202));
select profile_avatar_test.object(profile_avatar_test.request(203));
reset role;
create table profile_avatar_test.preserved as select to_jsonb(p)-array['avatar_url','updated_at'] value from public.profiles p where id=profile_avatar_test.id(3);
create function profile_avatar_test.fail_late() returns trigger language plpgsql as $$begin if new.request_nonce=profile_avatar_test.id(202) then raise exception 'Synthetic avatar ledger failure';end if;return new;end$$;
create trigger profile_avatar_fail_late before insert on private.mobile_profile_avatar_receipts for each row execute function profile_avatar_test.fail_late();
set role authenticated;
select profile_avatar_test.denied((select request from profile_avatar_test.pending where key='late'),'P0001');
reset role;
do $$begin assert (select avatar_url from public.profiles where id=profile_avatar_test.id(3))=(select receipt#>>'{current,avatarUrl}' from profile_avatar_test.cases where name='member-applied'),'Late ledger failure lost previous photo';end$$;
drop trigger profile_avatar_fail_late on private.mobile_profile_avatar_receipts;
update public.profiles set avatar_url='https://legacy.example.test/newer-photo' where id=profile_avatar_test.id(3);
set role authenticated;
select profile_avatar_test.capture('website-photo-conflict',(select request from profile_avatar_test.pending where key='cas'));
do $$declare saved record;begin select * into saved from profile_avatar_test.cases where name='member-applied';assert profile_avatar_test.rpc(saved.request)=saved.receipt,'Replay changed historical photo receipt';perform profile_avatar_test.denied(jsonb_set(saved.request,'{base,avatarUrl}','null'),'22023');end$$;
reset role;
do $$begin assert (select avatar_url from public.profiles where id=profile_avatar_test.id(3))='https://legacy.example.test/newer-photo','Replay overwrote later photo';assert (select to_jsonb(p)-array['avatar_url','updated_at'] from public.profiles p where id=profile_avatar_test.id(3))=(select value from profile_avatar_test.preserved),'Avatar changed profile fields';end$$;
update public.team_members set created_at='2026-10-24T00:00:00Z' where id=profile_avatar_test.id(10);
set role authenticated;
select profile_avatar_test.denied((select request from profile_avatar_test.pending where key='applied'),'42501');
reset role;
update public.team_members set created_at='2026-10-23T03:04:05.123456Z' where id=profile_avatar_test.id(10);
select set_config('request.jwt.claim.sub',profile_avatar_test.id(4)::text,false);
set role authenticated;
select profile_avatar_test.denied((select request from profile_avatar_test.pending where key='applied'),'42501');
reset role;
select set_config('request.jwt.claim.sub',profile_avatar_test.id(1)::text,false);
set role authenticated;
select profile_avatar_test.object(profile_avatar_test.request(210));
select profile_avatar_test.capture('owner-own-photo-applied',profile_avatar_test.request(210));
select profile_avatar_test.state('owner-own-photo');
do $$declare blocked boolean:=false;begin begin perform 1 from private.mobile_profile_avatar_receipts;exception when insufficient_privilege then blocked:=true;end;assert blocked,'Private avatar ledger exposed';end$$;
reset role;
do $$declare blocked boolean:=false;begin begin update private.mobile_profile_avatar_receipts set recorded_at=clock_timestamp();exception when others then blocked:=true;end;assert blocked,'Avatar ledger mutable';end$$;
set role anon;
do $$declare blocked boolean:=false;begin begin perform public.mobile_read_profile_avatar_state(null,null);exception when insufficient_privilege then blocked:=true;end;assert blocked,'Anonymous avatar read accepted';end$$;
reset role;

